require __DIR__.'/bootstrap.php';
require __DIR__.'/ticket_service.php';
saas_require_login();
$orgId=saas_require_organization(); $tourId=saas_require_tour(); saas_require_permission('passenger.create');
$db=saas_db(); $org=saas_current_organization(); $tour=saas_current_tour(); $user=saas_current_user();
$error='';$ok='';$search=trim((string)($_GET['q']??''));
$passengerFields=['phone'=>true,'email'=>true,'national_id'=>true,'date_of_birth'=>true,'gender'=>true,'blood_group'=>true,'address'=>true,'emergency_contact'=>true,'passport_number'=>true,'passport_copy'=>true,'visa_number'=>true,'visa_copy'=>true];
$q=$db->prepare("SELECT setting_value FROM tour_settings WHERE tour_id=? AND setting_key='passenger_form_fields' LIMIT 1");$q->execute([$tourId]);$savedPassengerFields=json_decode((string)$q->fetchColumn(),true);if(is_array($savedPassengerFields))$passengerFields=array_merge($passengerFields,array_map('boolval',$savedPassengerFields));
function upload_passenger_document(string $field,int $tourId,int $tpId,string $kind): string {
 if(empty($_FILES[$field]) || (int)$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE)return '';
 $f=$_FILES[$field];if((int)$f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Could not upload the '.$kind.'.');
 if((int)$f['size']>5*1024*1024)throw new RuntimeException('The '.$kind.' must be 5 MB or smaller.');
 $mime=(string)@mime_content_type((string)$f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))throw new RuntimeException('The '.$kind.' must be JPG, PNG, WebP or PDF.');
 $dir=__DIR__.'/uploads/tours/'.$tourId.'/passengers/'.$tpId;if(!is_dir($dir)&&!@mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Could not create the passenger document directory.');if(!is_writable($dir))throw new RuntimeException('Passenger document directory is not writable.');
 $name=$kind.'-'.bin2hex(random_bytes(8)).'.'.$allowed[$mime];if(!move_uploaded_file((string)$f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Could not save the '.$kind.'.');return '/uploads/tours/'.$tourId.'/passengers/'.$tpId.'/'.$name;
}
$editId=(int)($_GET['edit_id']??0);$filterDeparture=trim((string)($_GET['departure']??''));$filterBusId=(int)($_GET['bus_id']??0);
$bloodGroups=['A+','A-','B+','B-','AB+','AB-','O+','O-','Unknown'];
$paymentMethods=['CASH','BKASH','NAGAD','ROCKET','BANK','CARD','ONLINE','OTHER'];
$q=$db->prepare('SELECT default_fee FROM tours WHERE id=? AND organization_id=? LIMIT 1');$q->execute([$tourId,$orgId]);$tourFee=(float)($q->fetchColumn()??0);

if($_SERVER['REQUEST_METHOD']==='POST'){try{
 saas_check_csrf();$action=(string)($_POST['action']??'');
 $profileFields=function() use($db,$orgId){
  $name=trim((string)($_POST['full_name']??''));if($name==='')throw new RuntimeException('Passenger name is required.');
  return [$name,trim((string)($_POST['phone']??'')),trim((string)($_POST['email']??'')),trim((string)($_POST['national_id']??'')),trim((string)($_POST['date_of_birth']??'')),trim((string)($_POST['gender']??'')),trim((string)($_POST['blood_group']??'')),trim((string)($_POST['address']??'')),trim((string)($_POST['emergency_contact_name']??'')),trim((string)($_POST['emergency_contact_phone']??''))];
 };
 if($action==='register'){
  [$name,$phone,$email,$nid,$dob,$gender,$blood,$address,$ecName,$ecPhone]=$profileFields();
  $profileId=(int)($_POST['profile_id']??0);$passportNumber=$passengerFields['passport_number']?trim((string)($_POST['passport_number']??'')):'';$visaNumber=$passengerFields['visa_number']?trim((string)($_POST['visa_number']??'')):'';$departure=trim((string)($_POST['departure_from']??''));$discount=round(max(0,(float)($_POST['discount']??0)),2);$payNow=round(max(0,(float)($_POST['pay_now']??0)),2);$method=strtoupper(trim((string)($_POST['payment_method']??'CASH')));$ref=trim((string)($_POST['payment_reference']??''));
  if($discount>$tourFee)throw new RuntimeException('Discount cannot exceed the tour fee.');
  if($payNow>$tourFee-$discount+0.005)throw new RuntimeException('Initial payment cannot exceed the payable amount.');
  if(!in_array($method,$paymentMethods,true))throw new RuntimeException('Invalid payment method.');
  $db->beginTransaction();
  if($profileId){
   $q=$db->prepare('SELECT id FROM passenger_profiles WHERE id=? AND organization_id=? FOR UPDATE');$q->execute([$profileId,$orgId]);if(!$q->fetch())throw new RuntimeException('Passenger profile not found.');
   $q=$db->prepare('UPDATE passenger_profiles SET full_name=?,phone=?,email=?,national_id=?,date_of_birth=?,gender=?,blood_group=?,address=?,emergency_contact_name=?,emergency_contact_phone=? WHERE id=? AND organization_id=?');
   $q->execute([$name,$phone?:null,$email?:null,$nid?:null,$dob?:null,$gender?:null,$blood?:null,$address?:null,$ecName?:null,$ecPhone?:null,$profileId,$orgId]);
  }else{
   $q=$db->prepare('INSERT INTO passenger_profiles(organization_id,full_name,phone,email,national_id,date_of_birth,gender,blood_group,address,emergency_contact_name,emergency_contact_phone) VALUES(?,?,?,?,?,?,?,?,?,?,?)');
   $q->execute([$orgId,$name,$phone?:null,$email?:null,$nid?:null,$dob?:null,$gender?:null,$blood?:null,$address?:null,$ecName?:null,$ecPhone?:null]);$profileId=(int)$db->lastInsertId();
  }
  $q=$db->prepare('SELECT id FROM tour_passengers WHERE tour_id=? AND passenger_profile_id=? FOR UPDATE');$q->execute([$tourId,$profileId]);if($q->fetch())throw new RuntimeException('This passenger is already registered for this tour.');
  $q=$db->prepare("INSERT INTO tour_passengers(tour_id,passenger_profile_id,registration_source,fee,discount,departure_from,passport_number,visa_number,status) VALUES(?,?, 'ADMIN',?,?,?,?,?,'ACTIVE')");$q->execute([$tourId,$profileId,$tourFee,$discount,$departure?:null,$passportNumber?:null,$visaNumber?:null]);$tpId=(int)$db->lastInsertId();$passportCopy=$passengerFields['passport_copy']?upload_passenger_document('passport_copy',$tourId,$tpId,'passport-copy'):'';$visaCopy=$passengerFields['visa_copy']?upload_passenger_document('visa_copy',$tourId,$tpId,'visa-copy'):'';if($passportCopy!==''||$visaCopy!==''){$q=$db->prepare("UPDATE tour_passengers SET passport_copy=COALESCE(NULLIF(?,''),passport_copy),visa_copy=COALESCE(NULLIF(?,''),visa_copy) WHERE id=? AND tour_id=?");$q->execute([$passportCopy,$visaCopy,$tpId,$tourId]);}
  if($payNow>0){$paymentRef='PAY-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(4)));$q=$db->prepare('INSERT INTO payments(organization_id,tour_id,tour_passenger_id,payment_reference,amount,payment_method,transaction_reference,payment_date,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$orgId,$tourId,$tpId,$paymentRef,$payNow,$method,$ref?:null,date('Y-m-d'),'Initial payment during passenger registration',saas_user_id()]);if($tourFee-$discount-$payNow<=0.005)saas_issue_ticket($db,$tourId,$tpId,$orgId);}
  $db->commit();saas_audit('passenger.created','tour_passenger',$tpId,json_encode(['profile_id'=>$profileId,'initial_payment'=>$payNow],JSON_UNESCAPED_UNICODE));$ok=$payNow>0?'Passenger registered and initial payment recorded.':'Passenger registered successfully.';
 }elseif($action==='update'){
  saas_require_permission('passenger.edit');$tpId=(int)($_POST['tour_passenger_id']??0);$profileId=(int)($_POST['profile_id']??0);$keep=$db->prepare('SELECT pp.phone,pp.email,pp.national_id,pp.date_of_birth,pp.gender,pp.blood_group,pp.address,pp.emergency_contact_name,pp.emergency_contact_phone FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id WHERE tp.id=? AND tp.tour_id=? AND pp.organization_id=? LIMIT 1');$keep->execute([$tpId,$tourId,$orgId]);$currentProfile=$keep->fetch()?:[];$preserve=['phone'=>'phone','email'=>'email','national_id'=>'national_id','date_of_birth'=>'date_of_birth','gender'=>'gender','blood_group'=>'blood_group','address'=>'address','emergency_contact_name'=>'emergency_contact_name','emergency_contact_phone'=>'emergency_contact_phone'];foreach($preserve as $field=>$key){if(!$passengerFields[$field==='emergency_contact_name'||$field==='emergency_contact_phone'?'emergency_contact':$field] && !isset($_POST[$field]))$_POST[$field]=$currentProfile[$key]??'';}[$name,$phone,$email,$nid,$dob,$gender,$blood,$address,$ecName,$ecPhone]=$profileFields();$departure=trim((string)($_POST['departure_from']??''));$passportNumber=$passengerFields['passport_number']?trim((string)($_POST['passport_number']??'')):'';$visaNumber=$passengerFields['visa_number']?trim((string)($_POST['visa_number']??'')):'';$fee=round(max(0,(float)($_POST['fee']??0)),2);$discount=round(max(0,(float)($_POST['discount']??0)),2);if($discount>$fee)throw new RuntimeException('Discount cannot exceed the tour fee.');
  $db->beginTransaction();$q=$db->prepare('SELECT tp.id,tp.passenger_profile_id FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id WHERE tp.id=? AND tp.tour_id=? AND pp.organization_id=? FOR UPDATE');$q->execute([$tpId,$tourId,$orgId]);$row=$q->fetch();if(!$row||$profileId!==(int)$row['passenger_profile_id'])throw new RuntimeException('Passenger record not found.');
  $q=$db->prepare('UPDATE passenger_profiles SET full_name=?,phone=?,email=?,national_id=?,date_of_birth=?,gender=?,blood_group=?,address=?,emergency_contact_name=?,emergency_contact_phone=? WHERE id=? AND organization_id=?');$q->execute([$name,$phone?:null,$email?:null,$nid?:null,$dob?:null,$gender?:null,$blood?:null,$address?:null,$ecName?:null,$ecPhone?:null,$profileId,$orgId]);
  $q=$db->prepare('UPDATE tour_passengers SET fee=?,discount=?,departure_from=?,passport_number=?,visa_number=? WHERE id=? AND tour_id=?');$q->execute([$fee,$discount,$departure?:null,$passportNumber?:null,$visaNumber?:null,$tpId,$tourId]);$passportCopy=$passengerFields['passport_copy']?upload_passenger_document('passport_copy',$tourId,$tpId,'passport-copy'):'';$visaCopy=$passengerFields['visa_copy']?upload_passenger_document('visa_copy',$tourId,$tpId,'visa-copy'):'';if($passportCopy!==''||$visaCopy!==''){$q=$db->prepare("UPDATE tour_passengers SET passport_copy=COALESCE(NULLIF(?,''),passport_copy),visa_copy=COALESCE(NULLIF(?,''),visa_copy) WHERE id=? AND tour_id=?");$q->execute([$passportCopy,$visaCopy,$tpId,$tourId]);}$db->commit();saas_audit('passenger.updated','tour_passenger',$tpId);$ok='Passenger information updated.';$editId=$tpId;
 }elseif($action==='delete'){
  saas_require_permission('passenger.delete');$tpId=(int)($_POST['tour_passenger_id']??0);$db->beginTransaction();$q=$db->prepare('SELECT tp.id,pp.full_name FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id WHERE tp.id=? AND tp.tour_id=? AND t.organization_id=? FOR UPDATE');$q->execute([$tpId,$tourId,$orgId]);$p=$q->fetch();if(!$p)throw new RuntimeException('Passenger not found.');
  foreach(['payments','passenger_seat_assignments','room_assignments','tour_passenger_features','custom_field_values','ticket_instances'] as $table){$q=$db->prepare("SELECT COUNT(*) FROM {$table} WHERE tour_passenger_id=?");$q->execute([$tpId]);if((int)$q->fetchColumn()>0)throw new RuntimeException('This passenger has related payment, seat, room, option or ticket records. Remove those records first.');}
  $db->prepare('DELETE FROM tour_passengers WHERE id=? AND tour_id=?')->execute([$tpId,$tourId]);$db->commit();saas_audit('passenger.deleted','tour_passenger',$tpId);$ok='Passenger registration deleted. The reusable profile was kept.';
 }
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage()?:'Could not save passenger.';}}

$profiles=[];$passengers=[];
if($search!==''){$like='%'.$search.'%';$q=$db->prepare('SELECT id,full_name,phone,email,national_id,date_of_birth,gender,blood_group,address,emergency_contact_name,emergency_contact_phone FROM passenger_profiles WHERE organization_id=? AND (full_name LIKE ? OR phone LIKE ? OR email LIKE ? OR national_id LIKE ?) ORDER BY full_name LIMIT 20');$q->execute([$orgId,$like,$like,$like,$like]);$profiles=$q->fetchAll();}
$recentProfiles=[];$q=$db->prepare('SELECT id,full_name,phone,email,blood_group FROM passenger_profiles WHERE organization_id=? ORDER BY id DESC LIMIT 8');$q->execute([$orgId]);$recentProfiles=$q->fetchAll();
$q=$db->prepare("SELECT tp.id,tp.passenger_profile_id,tp.status,tp.fee,tp.discount,tp.departure_from,pp.full_name,pp.phone,pp.email,pp.blood_group,pp.emergency_contact_phone,COALESCE(p.paid,0) paid,COALESCE(f.feature_total,0) feature_total,b.name AS bus_name,b.bus_number,s.seat_code,r.room_no FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id LEFT JOIN (SELECT tour_id,tour_passenger_id,SUM(amount) paid FROM payments GROUP BY tour_id,tour_passenger_id) p ON p.tour_id=tp.tour_id AND p.tour_passenger_id=tp.id LEFT JOIN (SELECT tour_id,tour_passenger_id,SUM(total_price) feature_total FROM tour_passenger_features WHERE status='SELECTED' GROUP BY tour_id,tour_passenger_id) f ON f.tour_id=tp.tour_id AND f.tour_passenger_id=tp.id LEFT JOIN passenger_seat_assignments psa ON psa.tour_passenger_id=tp.id LEFT JOIN buses b ON b.id=psa.bus_id AND b.tour_id=tp.tour_id LEFT JOIN seats s ON s.id=psa.seat_id AND s.bus_id=psa.bus_id LEFT JOIN room_assignments ra ON ra.tour_passenger_id=tp.id LEFT JOIN rooms r ON r.id=ra.room_id AND r.tour_id=tp.tour_id WHERE tp.tour_id=? AND pp.organization_id=? AND (?='' OR COALESCE(tp.departure_from,'')=?) AND (?=0 OR psa.bus_id=?) GROUP BY tp.id ORDER BY tp.id DESC");$q->execute([$tourId,$orgId,$filterDeparture,$filterDeparture,$filterBusId,$filterBusId]);$passengers=$q->fetchAll();
$departureOptions=[];$q=$db->prepare("SELECT setting_value FROM tour_settings WHERE tour_id=? AND setting_key='departure_options' LIMIT 1");$q->execute([$tourId]);$decoded=json_decode((string)$q->fetchColumn(),true);if(is_array($decoded))$departureOptions=array_values(array_filter(array_map('strval',$decoded)));?>

<?php $editPassenger=null;if($editId){$q=$db->prepare('SELECT tp.*,pp.full_name,pp.phone,pp.email,pp.national_id,pp.date_of_birth,pp.gender,pp.blood_group,pp.address,pp.emergency_contact_name,pp.emergency_contact_phone,b.name AS bus_name,b.bus_number,s.seat_code,r.room_no FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id LEFT JOIN passenger_seat_assignments psa ON psa.tour_passenger_id=tp.id LEFT JOIN buses b ON b.id=psa.bus_id AND b.tour_id=tp.tour_id LEFT JOIN seats s ON s.id=psa.seat_id AND s.bus_id=psa.bus_id LEFT JOIN room_assignments ra ON ra.tour_passenger_id=tp.id LEFT JOIN rooms r ON r.id=ra.room_id AND r.tour_id=tp.tour_id WHERE tp.id=? AND tp.tour_id=? AND pp.organization_id=? LIMIT 1');$q->execute([$editId,$tourId,$orgId]);$editPassenger=$q->fetch()?:null;}
$q=$db->prepare("SELECT setting_value FROM tour_settings WHERE tour_id=? AND setting_key='banner_image' LIMIT 1");$q->execute([$tourId]);$banner=(string)($q->fetchColumn()??'');$baseUrl=rtrim((string)($config['app']['base_url']??''),'/');$publicUrl=$baseUrl.'/tour/'.rawurlencode((string)$tour['slug']);
$totalPassengers=count($passengers);$totalPaid=0;$totalDue=0;foreach($passengers as $p){$gross=max(0,(float)$p['fee']-(float)$p['discount']+(float)$p['feature_total']);$paid=(float)$p['paid'];$totalPaid+=$paid;$totalDue+=max(0,$gross-$paid);}
