<section class="card" style="margin-bottom:18px"><div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><div><h2 style="margin:0">Passenger filters</h2><p class="muted" style="margin:4px 0 0">Filter registered passengers by departure point or assigned bus.</p></div><a class="btn" href="passengers.php">Clear filters</a></div><form method="get" class="field-grid" style="margin-top:14px"><div class="field"><label>Departure</label><select name="departure"><option value="">All departures</option><?php foreach($departureOptions as $dep):?><option value="<?=saas_h($dep)?>" <?=$filterDeparture===$dep?'selected':''?>><?=saas_h($dep)?></option><?php endforeach;?></select></div><div class="field"><label>Bus</label><select name="bus_id"><option value="0">All buses</option><?php $fq=$db->prepare("SELECT id,name,bus_number FROM buses WHERE tour_id=? ORDER BY id");$fq->execute([$tourId]);foreach($fq->fetchAll() as $fb):?><option value="<?=$fb['id']?>" <?=$filterBusId===(int)$fb['id']?'selected':''?>><?=saas_h($fb['name'].' · '.$fb['bus_number'])?></option><?php endforeach;?></select></div><div class="field full"><button class="btn primary" type="submit">Apply filters</button></div></form></section><section class="card export-card"><div style="display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap"><div><h2 style="margin:0">Passenger list export</h2><p class="muted" style="margin:4px 0 0">Export the complete passenger list with gender, blood group, bus, seat and room details.</p></div><div class="actions" style="margin:0"><a class="btn primary" target="_blank" rel="noopener" href="export.php?type=passengers&format=pdf">📄 Export All Passengers — PDF</a><a class="btn" href="export.php?type=passengers&format=excel">📊 Export All Passengers — Excel</a></div></div></section><section class="card"><div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px"><div><h2>Registered passengers</h2><p class="subtext" style="margin:3px 0 0">Edit, collect payment, issue ticket or delete a clean registration.</p></div></div><div class="tablewrap"><table><thead><tr><th>Passenger</th><th>Departure</th><th>Bus / Seat</th><th>Room</th><th>Blood</th><th>Fee</th><th>Discount</th><th>Net</th><th>Paid</th><th>Due</th><th>Status</th><th>Options</th></tr></thead><tbody><?php foreach($passengers as $p):$gross=max(0,(float)$p['fee']-(float)$p['discount']+(float)$p['feature_total']);$due=max(0,$gross-(float)$p['paid']);?><tr><td><div class="person-name"><?=saas_h($p['full_name'])?></div><div class="person-meta"><?=saas_h($p['phone']??'')?><?=!empty($p['emergency_contact_phone'])?' · Emergency: '.saas_h($p['emergency_contact_phone']):''?></div></td><td><?=saas_h($p['departure_from']??'—')?></td><td><?php if(!empty($p['seat_code'])):?><span class="assignment-badge"><?=saas_h((string)$p['seat_code'])?></span><div class="person-meta"><?=saas_h(trim((string)($p['bus_name']??'').' '.(string)($p['bus_number']??'')))?></div><?php else:?><span class="assignment-badge muted">Not assigned</span><?php endif;?></td><td><?php if(!empty($p['room_no'])):?><span class="assignment-badge room"><?=saas_h((string)$p['room_no'])?></span><?php else:?><span class="assignment-badge muted">Not assigned</span><?php endif;?></td><td><?=saas_h($p['blood_group']??'—')?></td><td><?=number_format((float)$p['fee'],2)?></td><td><?=number_format((float)$p['discount'],2)?></td><td><?=number_format($gross,2)?></td><td><?=number_format((float)$p['paid'],2)?></td><td><span class="pill <?=$due>0?'red':'green'?>"><?=number_format($due,2)?></span></td><td><span class="pill"><?=saas_h($p['status'])?></span></td><td><div class="actions"><a class="btn small" href="passengers.php?edit_id=<?=$p['id']?>">Edit</a><a class="btn small" href="payments.php?passenger_id=<?=$p['id']?>">Payment</a><a class="btn small" href="ticket_issue.php?passenger_id=<?=$p['id']?>">Ticket</a><?php if(saas_can('passenger.delete')):?><form method="post" onsubmit="return confirm('Delete this tour registration? This is allowed only when there are no related records.');"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="tour_passenger_id" value="<?=$p['id']?>"><button class="btn small delete-btn" type="submit">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$passengers):?><tr><td colspan="12"><div class="empty">No passengers registered yet.</div></td></tr><?php endif;?></tbody></table></div></section>
</main></div>
<script>
const sb=document.getElementById('settingsBtn'),sm=document.getElementById('settingsMenu');sb?.addEventListener('click',()=>{const o=sm.classList.toggle('open');sb.setAttribute('aria-expanded',o?'true':'false');});
function useProfile(id,d){document.getElementById('profile_id').value=id;['full_name','phone','email','national_id','date_of_birth','gender','blood_group','address','emergency_contact_name','emergency_contact_phone'].forEach(k=>{const el=document.getElementById(k);if(el)el.value=d[k]||'';});document.getElementById('passengerForm').scrollIntoView({behavior:'smooth',block:'start'});}
function money(v){const n=parseFloat(v);return Number.isFinite(n)?n:0;}function updatePrice(){const fee=money(document.getElementById('fee')?.value),discount=Math.min(money(document.getElementById('discount')?.value),fee),net=Math.max(0,fee-discount),pay=document.getElementById('pay_now')?Math.min(money(document.getElementById('pay_now').value),net):0;document.getElementById('feeDisplay').textContent=fee.toFixed(2);document.getElementById('discountDisplay').textContent=discount.toFixed(2);document.getElementById('netDisplay').textContent=net.toFixed(2);document.getElementById('dueDisplay').textContent=Math.max(0,net-pay).toFixed(2);if(document.getElementById('pay_now'))document.getElementById('pay_now').max=net.toFixed(2);}document.getElementById('fee')?.addEventListener('input',updatePrice);document.getElementById('discount')?.addEventListener('input',updatePrice);document.getElementById('pay_now')?.addEventListener('input',updatePrice);updatePrice();
</script></body></html>